#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minimumEffort(vector<vector<int>>& tasks) {
        sort(tasks.begin(), tasks.end(), [](const vector<int>& a, const vector<int>& b) {
            return (a[1] - a[0]) > (b[1] - b[0]);
        });
        int curr = 0, initial = 0;
        for (const auto& t : tasks) {
            int actual = t[0], minimum = t[1];
            if (curr < minimum) {
                initial += minimum - curr;
                curr = minimum;
            }
            curr -= actual;
        }
        return initial;
    }
};

import java.util.*;

class Solution {
    public int minimumEffort(int[][] tasks) {
        Arrays.sort(tasks, (a, b) -> Integer.compare(b[1] - b[0], a[1] - a[0]));
        int curr = 0, initial = 0;
        for (int[] t : tasks) {
            int actual = t[0], minimum = t[1];
            if (curr < minimum) {
                initial += minimum - curr;
                curr = minimum;
            }
            curr -= actual;
        }
        return initial;
    }
}

/**
 * @param {number[][]} tasks
 * @return {number}
 */
var minimumEffort = function(tasks) {
    tasks.sort((a, b) => (b[1] - b[0]) - (a[1] - a[0]));
    let curr = 0, initial = 0;
    for (const [actual, minimum] of tasks) {
        if (curr < minimum) {
            initial += minimum - curr;
            curr = minimum;
        }
        curr -= actual;
    }
    return initial;
};
